import { Sprite, SpriteMaterial, Vector3 } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { atlasRegion, imageUrl, position, scale } = config;
  const { x: sx, y: sy, width: sw, height: sh } = atlasRegion;

  // Load the atlas texture (cached)
  const texture = ctx.textureLoader.load(imageUrl);

  // Compute UV offset and repeat so the geometry maps only the atlas region
  const texW = texture.image.width;
  const texH = texture.image.height;
  const u0 = sx / texW;
  const v0 = sy / texH;
  const u1 = (sx + sw) / texW;
  const v1 = (sy + sh) / texH;
  texture.offset.set(u0, v0);
  texture.repeat.set(u1 - u0, v1 - v0);

  // Create sprite material and sprite
  const material = new SpriteMaterial({ map: texture });
  const sprite = new Sprite(material);

  // Set size: base width 1, height to match atlas region aspect ratio
  const aspect = sh / sw;
  const baseWidth = 1;
  const baseHeight = baseWidth * aspect;

  // Apply config scale
  const sc = scale || [1, 1, 1];
  sprite.scale.set(baseWidth * sc[0], baseHeight * sc[1], 1 * sc[2]);

  // Position
  if (position) {
    sprite.position.copy(new Vector3(position[0], position[1], position[2]));
  }

  // Cleanup
  sprite.userData.cleanup = () => {
    texture.dispose();
    material.dispose();
  };

  return sprite;
}
